                    .filter(d -> d.handlerId().equals(handlerId)).findFirst();
            if (own.isPresent()) {
                return new StoredResponse(200, toJson(toResponse(target, null)));
            }
            if (status == YieldStatus.DISPOSITION_CLEARED) {
                throw ApiException.conflict("两名不同处置人已确认，门禁已解除");
            }

